def deduplicate_shared_foods(apps, schema_editor):
    Food = apps.get_model('core', 'Food')
    MealItem = apps.get_model('core', 'MealItem')
    RecognitionResult = apps.get_model('core', 'RecognitionResult')
    FoodDetection = apps.get_model('core', 'FoodDetection')
    FoodNutrition = apps.get_model('core', 'FoodNutrition')
    NutritionRecord = apps.get_model('core', 'NutritionRecord')

    seen = {}
    for food in Food.objects.filter(created_by__isnull=True).order_by('id'):
        if food.name not in seen:
            seen[food.name] = food
        else:
            primary = seen[food.name]
            MealItem.objects.filter(food=food).update(food=primary)
            RecognitionResult.objects.filter(food=food).update(food=primary)
            FoodDetection.objects.filter(food=food).update(food=primary)
            FoodNutrition.objects.filter(food=food).delete()
            NutritionRecord.objects.filter(food=food).delete()
            food.delete()


